<?php
require_once dirname(__DIR__) . '/config.php';
$search = mb_substr(input('q',$_GET),0,100); $gender = input('gender',$_GET);
$rows = students($search,$gender); $total = count(students()); $filtered = count($rows); $pages = max(1,(int)ceil($filtered/8)); $page = min($pages,max(1,student_id($_GET['page'] ?? '1'))); $offset = ($page-1)*8;
page_start('Data siswa','siswa'); heading('DIREKTORI PENDAFTARAN','Setiap nama, sebuah masa depan.','Temukan, periksa, dan perbarui data calon siswa.',true);
?>
<section class="panel"><div class="panel-heading"><div><h2>Daftar calon siswa <span class="count-pill"><?=$total?></span></h2><p>Seluruh pendaftaran dalam ruang demo Anda.</p></div><span class="tag">DATA PENDAFTAR</span></div><form class="filters" method="get" action="/list-siswa.php"><div class="search-field"><?=icon('search')?><label class="sr-only" for="q">Cari nama atau sekolah asal</label><input id="q" name="q" value="<?=e($search)?>" maxlength="100" placeholder="Cari nama atau sekolah asal..."></div><label class="sr-only" for="gender">Filter jenis kelamin</label><select id="gender" name="gender"><option value="">Semua jenis kelamin</option><?php foreach (GENDERS as $g): ?><option <?=$g === $gender ? 'selected' : ''?>><?=e($g)?></option><?php endforeach ?></select><button class="button" type="submit">Terapkan</button><?php if ($search !== '' || $gender !== ''): ?><a class="button secondary" href="/list-siswa.php">Reset</a><?php endif ?></form><?php if (!$filtered): ?><div class="empty"><?=icon('search')?><h2><?=$total ? 'Siswa belum ditemukan' : 'Belum ada pendaftar'?></h2><p><?=$total ? 'Coba nama lain atau hapus filter pencarian.' : 'Mulai dengan menambahkan siswa pertama Anda.'?></p><a class="button secondary" href="<?=$total ? '/list-siswa.php' : '/form-daftar.php'?>"><?=$total ? 'Lihat seluruh siswa' : 'Tambah siswa'?></a></div><?php else: student_table(array_slice($rows,$offset,8),false,$offset); endif ?><div class="panel-foot"><span><?=$filtered ? ($offset+1).'-'.min($offset+8,$filtered) : '0'?> dari <?=$filtered?> siswa<?php if ($filtered !== $total): ?> (total <?=$total?>)<?php endif ?></span><nav class="pagination" aria-label="Halaman daftar siswa"><?php for ($i=1;$i<=$pages;$i++): ?><a href="?<?=e(http_build_query(['q'=>$search,'gender'=>$gender,'page'=>$i]))?>" <?=$page===$i ? 'aria-current="page"' : ''?>><?=$i?></a><?php endfor ?></nav></div></section><div class="demo-note"><?=icon('info')?><p>Hapus siswa akan membuka halaman konfirmasi. Data hanya dihapus setelah Anda menekan tombol konfirmasi.</p></div>
<?php page_end(); ?>
